-- Preserve signed v2 releases while admitting the provider-disclosed v3 release.
ALTER TABLE "wireline_live_voices" DROP CONSTRAINT IF EXISTS "wireline_live_voices_biometric_release_check";--> statement-breakpoint
ALTER TABLE "wireline_live_voices" ADD CONSTRAINT "wireline_live_voices_biometric_release_check" CHECK ("wireline_live_voices"."biometric_release_version" IS NOT NULL AND "wireline_live_voices"."biometric_release_version" IN ('voice-release-v2-2026-10-24', 'voice-release-v3-2026-11-07') AND "wireline_live_voices"."biometric_release_signed_name" IS NOT NULL AND char_length("wireline_live_voices"."biometric_release_signed_name") BETWEEN 3 AND 120 AND "wireline_live_voices"."biometric_release_accepted_at" IS NOT NULL AND char_length("wireline_live_voices"."consent_notice_text") BETWEEN 200 AND 8000);